const householdValueLabel = (value: string, locale: AppLocale) => locale === "bn" ? householdValueBn[value] ?? value.replaceAll("_", " ") : value.replaceAll("_", " ");

function initial(kind: Kind, householdId = "", listId = ""): Form {
  if (kind === "household") return {};
  if (kind === "list") return { householdId, budgetAmount: "0", neededBy: today() };
  if (kind === "item") return { listId, category: "grocery", quantity: "1", unit: "pcs", estimatedCost: "0", priority: "normal" };
  if (kind === "bill") return { householdId, category: "electricity", billingMonth: today(), dueDate: today(), recurrence: "monthly", amount: "" };
  if (kind === "task") return { householdId, category: "cleaning", dueAt: nowLocal(), recurrence: "none", priority: "normal" };
  if (kind === "contact") return { householdId, serviceType: "electrician", rating: "0", isTrusted: "false" };
  return { householdId, category: "electrical", urgency: "normal", estimatedCost: "0", scheduledAt: "" };
}

export function HouseholdCenter() {
  const { locale, pick } = useLocale();
  const money = useMemo(() => new Intl.NumberFormat(locale === "bn" ? "bn-BD" : "en-BD", { style: "currency", currency: "BDT", minimumFractionDigits: 0, maximumFractionDigits: 2 }), [locale]);
  const date = useMemo(() => new Intl.DateTimeFormat(locale === "bn" ? "bn-BD" : "en-BD", { dateStyle: "medium" }), [locale]);
  const [family, setFamily] = useState<HouseholdPayload["family"]>();
  const [households, setHouseholds] = useState<Household[]>([]);
  const [lists, setLists] = useState<ShoppingList[]>([]);
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [bills, setBills] = useState<UtilityBill[]>([]);
  const [tasks, setTasks] = useState<HouseholdTask[]>([]);
  const [contacts, setContacts] = useState<ServiceContact[]>([]);
  const [maintenance, setMaintenance] = useState<MaintenanceRequest[]>([]);
  const [documents, setDocuments] = useState<HouseholdDocument[]>([]);
  const [canManage, setCanManage] = useState(false);
  const [selectedHousehold, setSelectedHousehold] = useState("all");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [exporting, setExporting] = useState(false);
  const [migrationRequired, setMigrationRequired] = useState(false);
  const [setupRequired, setSetupRequired] = useState(false);
  const [feedback, setFeedback] = useActionFeedback();
  const [kind, setKind] = useState<Kind | null>(null);
  const [editingRecord, setEditingRecord] = useState<{ id: string; kind: Kind } | null>(null);
  const [form, setForm] = useState<Form>({});
  const [uploadOpen, setUploadOpen] = useState(false);
  const [uploadForm, setUploadForm] = useState<Form>({ documentType: "receipt" });
  const [uploadFile, setUploadFile] = useState<File | null>(null);
  const [statusDraft, setStatusDraft] = useState<StatusDraft | null>(null);

  const load = useCallback(async () => {
    try {
      const response = await fetch("/api/household", { cache: "no-store" }); const payload = await response.json() as HouseholdPayload;
      if (payload.code === "FAMILY_SETUP_REQUIRED") { setSetupRequired(true); setFamily(undefined); setHouseholds([]); setLists([]); setItems([]); setBills([]); setTasks([]); setContacts([]); setMaintenance([]); setDocuments([]); setCanManage(false); setMigrationRequired(false); return; }
      if (!response.ok) throw new Error(payload.error ?? pick("হাউসহোল্ড কর্মক্ষেত্র লোড হয়নি।", "Could not load the household workspace."));
      setFamily(payload.family); setHouseholds(payload.households ?? []); setLists(payload.shoppingLists ?? []); setItems(payload.shoppingItems ?? []); setBills(payload.bills ?? []); setTasks(payload.tasks ?? []); setContacts(payload.contacts ?? []); setMaintenance(payload.maintenance ?? []); setDocuments(payload.documents ?? []); setCanManage(Boolean(payload.permissions?.canManage)); setMigrationRequired(Boolean(payload.migrationRequired)); setSetupRequired(false);
    } catch (error) { setFamily(undefined); setHouseholds([]); setLists([]); setItems([]); setBills([]); setTasks([]); setContacts([]); setMaintenance([]); setDocuments([]); setCanManage(false); setMigrationRequired(false); setFeedback(error instanceof Error ? error.message : pick("হাউসহোল্ড কর্মক্ষেত্র লোড হয়নি।", "Could not load the household workspace.")); }
    finally { setLoading(false); }
  }, [pick, setFeedback]);
  useEffect(() => { queueMicrotask(() => void load()); }, [load]);

  const visibleHouseholds = households.filter((item) => item.status === "active");
  const listIds = useMemo(() => new Set(lists.filter((item) => selectedHousehold === "all" || item.household_id === selectedHousehold).map((item) => item.id)), [lists, selectedHousehold]);
  const filteredLists = lists.filter((item) => selectedHousehold === "all" || item.household_id === selectedHousehold);
  const filteredItems = items.filter((item) => listIds.has(item.list_id));
  const filteredBills = bills.filter((item) => selectedHousehold === "all" || item.household_id === selectedHousehold);
  const filteredTasks = tasks.filter((item) => selectedHousehold === "all" || item.household_id === selectedHousehold);
  const filteredMaintenance = maintenance.filter((item) => selectedHousehold === "all" || item.household_id === selectedHousehold);
  const openItems = filteredItems.filter((item) => item.status === "needed");
  const openTasks = filteredTasks.filter((item) => ["todo", "in_progress"].includes(item.status));
  const dueBills = filteredBills.filter((item) => effectiveBillStatus(item) !== "paid" && effectiveBillStatus(item) !== "skipped");
  const dueAmount = dueBills.reduce((sum, item) => sum + n(item.amount), 0);
  const openMaintenance = filteredMaintenance.filter((item) => !["completed", "cancelled"].includes(item.status));

  function householdName(id: string) { return households.find((item) => item.id === id)?.name ?? pick("বাসা", "Household"); }
  function listName(id: string) { return lists.find((item) => item.id === id)?.title ?? pick("বাজারের তালিকা", "Shopping list"); }
  function openCreate(next: Kind, seed: Form = {}) { const householdId = selectedHousehold !== "all" ? selectedHousehold : visibleHouseholds[0]?.id ?? ""; setEditingRecord(null); setKind(next); setForm({ ...initial(next, householdId, filteredLists.find((item) => item.status === "active")?.id ?? ""), ...seed }); }
  function openEdit(next: Kind, item: EditableHouseholdRecord) { const value = item as unknown as Record<string, unknown>; const forms: Record<Kind, Form> = {
    household: { name: String(value.name ?? ""), address: String(value.address ?? ""), city: String(value.city ?? ""), notes: String(value.notes ?? "") },
    list: { householdId: String(value.household_id ?? ""), title: String(value.title ?? ""), description: String(value.description ?? ""), budgetAmount: String(value.budget_amount ?? 0), neededBy: String(value.needed_by ?? "") },
    item: { listId: String(value.list_id ?? ""), itemName: String(value.item_name ?? ""), category: String(value.category ?? "grocery"), quantity: String(value.quantity ?? 1), unit: String(value.unit ?? "pcs"), estimatedCost: String(value.estimated_cost ?? 0), priority: String(value.priority ?? "normal"), assignedToName: String(value.assigned_to_name ?? ""), notes: String(value.notes ?? "") },
    bill: { householdId: String(value.household_id ?? ""), title: String(value.title ?? ""), category: String(value.category ?? "other"), provider: String(value.provider ?? ""), accountNumber: String(value.account_number ?? ""), billingMonth: String(value.billing_month ?? today()).slice(0, 10), amount: String(value.amount ?? ""), dueDate: String(value.due_date ?? today()), recurrence: String(value.recurrence ?? "monthly"), notes: String(value.notes ?? "") },
    task: { householdId: String(value.household_id ?? ""), title: String(value.title ?? ""), category: String(value.category ?? "other"), assignedToName: String(value.assigned_to_name ?? ""), dueAt: value.due_at ? new Date(String(value.due_at)).toISOString().slice(0, 16) : "", recurrence: String(value.recurrence ?? "none"), priority: String(value.priority ?? "normal"), notes: String(value.notes ?? "") },
    contact: { householdId: String(value.household_id ?? ""), name: String(value.name ?? ""), serviceType: String(value.service_type ?? "other"), phone: String(value.phone ?? ""), alternatePhone: String(value.alternate_phone ?? ""), address: String(value.address ?? ""), rating: String(value.rating ?? 0), isTrusted: String(Boolean(value.is_trusted)), notes: String(value.notes ?? "") },
    maintenance: { householdId: String(value.household_id ?? ""), serviceContactId: String(value.service_contact_id ?? ""), title: String(value.title ?? ""), description: String(value.description ?? ""), category: String(value.category ?? "other"), urgency: String(value.urgency ?? "normal"), estimatedCost: String(value.estimated_cost ?? 0), assignedVendorName: String(value.assigned_vendor_name ?? ""), scheduledAt: value.scheduled_at ? new Date(String(value.scheduled_at)).toISOString().slice(0, 16) : "" },
  }; setEditingRecord({ id: item.id, kind: next }); setKind(next); setForm(forms[next]); }
  async function action(actionName: string, data: Record<string, unknown>) { const response = await fetch("/api/household/records", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: actionName, data }) }); if (response.status === 499) return false; const payload = await response.json() as { error?: string }; if (!response.ok) throw new Error(payload.error ?? pick("রেকর্ড সংরক্ষণ হয়নি।", "The record could not be saved.")); return true; }
  async function create() { if (!kind) return; const recordKind = kind; const wasEditing = Boolean(editingRecord); setSaving(true); try { if (editingRecord) { const response = await fetch("/api/household/records", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ kind, recordId: editingRecord.id, data: form }) }); if (response.status === 499) return; const payload = await response.json() as { error?: string }; if (!response.ok) throw new Error(payload.error ?? pick("রেকর্ড আপডেট হয়নি।", "The record could not be updated.")); } else if (!(await action(`create_${kind}`, form))) return; setKind(null); setEditingRecord(null); await load(); setFeedback(pick(`${titlesBn[recordKind]} ${wasEditing ? "হালনাগাদ" : "সংরক্ষণ"} হয়েছে।`, `${titlesEn[recordKind]} was ${wasEditing ? "updated" : "saved"}.`)); } catch (error) { setFeedback(error instanceof Error ? error.message : pick("রেকর্ড সংরক্ষণ হয়নি।", "The record could not be saved.")); } finally { setSaving(false); } }
  async function remove(recordKind: Kind, recordId: string) { setSaving(true); try { const response = await fetch("/api/household/records", { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ kind: recordKind, recordId }) }); if (response.status === 499) return; const payload = await response.json() as { error?: string; message?: string }; if (!response.ok) throw new Error(payload.error ?? pick("মোছা যায়নি।", "Delete failed.")); await load(); setFeedback(payload.message ?? pick("রেকর্ড মোছা হয়েছে।", "Record deleted.")); } catch (error) { setFeedback(error instanceof Error ? error.message : pick("মোছা যায়নি।", "Delete failed.")); } finally { setSaving(false); } }
  async function status(entity: string, id: string, value: string, extra: Record<string, unknown> = {}) { setSaving(true); try { if (!(await action("update_status", { entity, id, status: value, ...extra }))) return false; await load(); setFeedback(pick(`স্ট্যাটাস ${householdValueLabel(value, locale)} করা হয়েছে।`, `Status changed to ${householdValueLabel(value, locale)}.`)); return true; } catch (error) { setFeedback(error instanceof Error ? error.message : pick("স্ট্যাটাস হালনাগাদ হয়নি।", "Status update failed.")); return false; } finally { setSaving(false); } }
  async function submitStatusDraft() {
    if (!statusDraft) return;
    let succeeded = false;
    if (statusDraft.kind === "item") {
      const cost = Number(statusDraft.actualCost);
      if (!statusDraft.actualCost.trim() || !Number.isFinite(cost) || cost < 0) { setFeedback(pick("সঠিক প্রকৃত খরচ দিন।", "Enter a valid actual cost.")); return; }
      succeeded = await status("item", statusDraft.item.id, "purchased", { actualCost: cost });
    } else if (statusDraft.kind === "bill") {
      succeeded = await status("bill", statusDraft.bill.id, "paid", { paymentMethod: statusDraft.paymentMethod, reference: statusDraft.reference.trim() });
    } else {
      const extra: Record<string, unknown> = { assignedVendorName: statusDraft.vendor.trim() };
      if (statusDraft.nextStatus === "completed") {
        const cost = Number(statusDraft.actualCost);
        if (!statusDraft.actualCost.trim() || !Number.isFinite(cost) || cost < 0) { setFeedback(pick("সঠিক প্রকৃত খরচ দিন।", "Enter a valid actual cost.")); return; }
        extra.actualCost = cost;
      }
      if (statusDraft.nextStatus === "scheduled") {
        if (!statusDraft.scheduledAt || Number.isNaN(Date.parse(statusDraft.scheduledAt))) { setFeedback(pick("সঠিক সময়সূচি দিন।", "Enter a valid schedule.")); return; }
        extra.scheduledAt = statusDraft.scheduledAt;
      }
      succeeded = await status("maintenance", statusDraft.request.id, statusDraft.nextStatus, extra);
    }
    if (succeeded) setStatusDraft(null);
  }

  const uploadTargets = useMemo(() => [
    ...lists.map((item) => ({ value: `shopping_list:${item.id}`, label: `${pick("বাজার", "Shopping")} · ${item.title}` })),
    ...bills.map((item) => ({ value: `bill:${item.id}`, label: `${pick("বিল", "Bill")} · ${item.title}` })),
    ...maintenance.map((item) => ({ value: `maintenance:${item.id}`, label: `${pick("মেরামত", "Maintenance")} · ${item.title}` })),
  ], [bills, lists, maintenance, pick]);
  async function upload() { if (!uploadFile || !uploadForm.target) { setFeedback(pick("ফাইল ও সংযুক্ত রেকর্ড নির্বাচন করুন।", "Select a file and linked record.")); return; } const [entityType, entityId] = uploadForm.target.split(":"); const body = new FormData(); body.set("file", uploadFile); body.set("entityType", entityType); body.set("entityId", entityId); body.set("documentType", uploadForm.documentType || "other"); body.set("title", uploadForm.title || uploadFile.name); setSaving(true); try { const response = await fetch("/api/household/upload", { method: "POST", body }); if (response.status === 499) return; const payload = await response.json() as { error?: string }; if (!response.ok) throw new Error(payload.error ?? pick("আপলোড হয়নি।", "Upload failed.")); setUploadOpen(false); setUploadFile(null); setUploadForm({ documentType: "receipt" }); await load(); setFeedback(pick("ডকুমেন্ট ভল্টে সংরক্ষণ হয়েছে।", "The document was saved to the vault.")); } catch (error) { setFeedback(error instanceof Error ? error.message : pick("আপলোড হয়নি।", "Upload failed.")); } finally { setSaving(false); } }
  async function deleteDocument(id: string) { setSaving(true); try { const response = await fetch(`/api/household-document/${id}`, { method: "DELETE" }); if (response.status === 499) return; const payload = await response.json() as { error?: string; message?: string }; if (!response.ok) throw new Error(payload.error ?? pick("ডকুমেন্ট মোছা যায়নি।", "Document could not be deleted.")); await load(); setFeedback(payload.message ?? pick("ডকুমেন্ট মোছা হয়েছে।", "Document deleted.")); } catch (error) { setFeedback(error instanceof Error ? error.message : pick("ডকুমেন্ট মোছা যায়নি।", "Document could not be deleted.")); } finally { setSaving(false); } }

  async function exportXlsx() {
    setExporting(true); try {
      const XLSX = await import("xlsx"), workbook = XLSX.utils.book_new(); const add = (bn: string, en: string, rows: Array<Record<string, unknown>>) => XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(rows), locale === "bn" ? bn : en);
      add("বাসাসমূহ", "Households", households.map((item) => ({ [pick("নাম", "Name")]: item.name, [pick("ঠিকানা", "Address")]: item.address ?? "", [pick("শহর", "City")]: item.city ?? "", [pick("অবস্থা", "Status")]: householdValueLabel(item.status, locale), [pick("নোট", "Notes")]: item.notes ?? "" })));
      add("বাজারের তালিকা", "Shopping Lists", lists.map((item) => ({ [pick("বাসা", "Household")]: householdName(item.household_id), [pick("তালিকা", "List")]: item.title, [pick("বাজেট", "Budget")]: n(item.budget_amount), [pick("প্রয়োজনের তারিখ", "Needed by")]: item.needed_by ?? "", [pick("অবস্থা", "Status")]: householdValueLabel(item.status, locale), [pick("তৈরিকারী", "Creator")]: item.created_by_name })));
      add("বাজারের আইটেম", "Shopping Items", items.map((item) => ({ [pick("তালিকা", "List")]: listName(item.list_id), [pick("আইটেম", "Item")]: item.item_name, [pick("শ্রেণি", "Category")]: householdValueLabel(item.category, locale), [pick("পরিমাণ", "Quantity")]: n(item.quantity), [pick("একক", "Unit")]: householdValueLabel(item.unit, locale), [pick("আনুমানিক", "Estimated")]: n(item.estimated_cost), [pick("প্রকৃত", "Actual")]: n(item.actual_cost), [pick("অগ্রাধিকার", "Priority")]: householdValueLabel(item.priority, locale), [pick("দায়িত্বপ্রাপ্ত", "Assigned")]: item.assigned_to_name ?? "", [pick("অবস্থা", "Status")]: householdValueLabel(item.status, locale), [pick("ক্রেতা", "Purchased by")]: item.purchased_by_name ?? "" })));
      add("ইউটিলিটি বিল", "Utility Bills", bills.map((item) => ({ [pick("বাসা", "Household")]: householdName(item.household_id), [pick("বিল", "Bill")]: item.title, [pick("শ্রেণি", "Category")]: householdValueLabel(item.category, locale), [pick("সেবাদাতা", "Provider")]: item.provider ?? "", [pick("অ্যাকাউন্ট", "Account")]: item.account_number ?? "", [pick("মাস", "Month")]: item.billing_month, [pick("পরিমাণ", "Amount")]: n(item.amount), [pick("শেষ তারিখ", "Due")]: item.due_date, [pick("পুনরাবৃত্তি", "Recurrence")]: householdValueLabel(item.recurrence, locale), [pick("অবস্থা", "Status")]: householdValueLabel(effectiveBillStatus(item), locale), [pick("পদ্ধতি", "Method")]: item.payment_method ? householdValueLabel(item.payment_method, locale) : "", [pick("রেফারেন্স", "Reference")]: item.reference ?? "" })));
      add("কাজসমূহ", "Tasks", tasks.map((item) => ({ [pick("বাসা", "Household")]: householdName(item.household_id), [pick("কাজ", "Task")]: item.title, [pick("শ্রেণি", "Category")]: householdValueLabel(item.category, locale), [pick("দায়িত্বপ্রাপ্ত", "Assigned")]: item.assigned_to_name ?? "", [pick("শেষ সময়", "Due")]: item.due_at ?? "", [pick("পুনরাবৃত্তি", "Recurrence")]: householdValueLabel(item.recurrence, locale), [pick("অগ্রাধিকার", "Priority")]: householdValueLabel(item.priority, locale), [pick("অবস্থা", "Status")]: householdValueLabel(item.status, locale), [pick("সম্পন্নকারী", "Completed by")]: item.completed_by_name ?? "" })));
      add("মেরামত", "Maintenance", maintenance.map((item) => ({ [pick("বাসা", "Household")]: householdName(item.household_id), [pick("সমস্যা", "Issue")]: item.title, [pick("শ্রেণি", "Category")]: householdValueLabel(item.category, locale), [pick("জরুরিতা", "Urgency")]: householdValueLabel(item.urgency, locale), [pick("আনুমানিক", "Estimated")]: n(item.estimated_cost), [pick("প্রকৃত", "Actual")]: n(item.actual_cost), [pick("সেবাদাতা", "Vendor")]: item.assigned_vendor_name ?? "", [pick("সময়সূচি", "Schedule")]: item.scheduled_at ?? "", [pick("অবস্থা", "Status")]: householdValueLabel(item.status, locale), [pick("রিপোর্টকারী", "Reporter")]: item.reported_by_name })));
      add("সেবা ডিরেক্টরি", "Service Directory", contacts.map((item) => ({ [pick("সেবা", "Service")]: householdValueLabel(item.service_type, locale), [pick("নাম", "Name")]: item.name, [pick("ফোন", "Phone")]: item.phone, [pick("বিকল্প ফোন", "Alternate")]: item.alternate_phone ?? "", [pick("রেটিং", "Rating")]: n(item.rating), [pick("বিশ্বস্ত", "Trusted")]: item.is_trusted ? pick("হ্যাঁ", "Yes") : pick("না", "No"), [pick("ঠিকানা", "Address")]: item.address ?? "", [pick("অবস্থা", "Status")]: householdValueLabel(item.status, locale) })));
      add("ডকুমেন্ট", "Documents", documents.map((item) => ({ [pick("শিরোনাম", "Title")]: item.title, [pick("ধরন", "Type")]: householdValueLabel(item.document_type, locale), [pick("রেকর্ড", "Entity")]: `${item.entity_type}:${item.entity_id}`, [pick("ফাইল", "File")]: item.file_name, [pick("আপলোডকারী", "Uploader")]: item.uploaded_by_name, [pick("তারিখ", "Date")]: item.created_at })));
      XLSX.writeFile(workbook, `${family?.name_en?.replace(/[^a-z0-9]+/gi, "-").toLowerCase() || "family"}-shared-household.xlsx`);
    } finally { setExporting(false); }
  }

  useEffect(() => {
    const modelContext = (document as Document & { modelContext?: { registerTool: (tool: Record<string, unknown>, options?: { signal?: AbortSignal }) => void | Promise<void> } }).modelContext; if (!modelContext?.registerTool) return; const lifecycle = new AbortController();
    void Promise.resolve(modelContext.registerTool({ name: "get_shared_household_summary", title: "Get shared household summary", description: "Read visible household counts, pending shopping items, due utility bills, open tasks and maintenance issues.", inputSchema: { type: "object", properties: {}, additionalProperties: false }, annotations: { readOnlyHint: true, untrustedContentHint: true }, execute(input: unknown) { if (!input || typeof input !== "object" || Array.isArray(input) || Object.keys(input as object).length) throw new Error("No input fields are accepted."); return { households: visibleHouseholds.map((item) => item.name), shoppingItemsNeeded: openItems.length, utilityBillsDue: dueBills.length, utilityAmountDue: dueAmount, openTasks: openTasks.length, openMaintenance: openMaintenance.length }; } }, { signal: lifecycle.signal })).catch(() => undefined); return () => lifecycle.abort();
  }, [dueAmount, dueBills.length, openItems.length, openMaintenance.length, openTasks.length, visibleHouseholds]);

  if (loading) return <main className="grid min-h-[calc(100vh-4rem)] place-items-center"><LoaderCircle className="size-7 animate-spin text-primary" /></main>;
  if (setupRequired) return <main className="mx-auto max-w-3xl p-6 md:p-10"><Empty icon={<Users />} title={pick("ফ্যামিলি অ্যাক্সেস সক্রিয় নয়", "Family access is not active")} text={pick("জয়েন কোড দিয়ে আবেদন করুন। অ্যাডমিন অনুমোদনের পর শেয়ার্ড হাউসহোল্ড ব্যবহার করা যাবে।", "Apply with a join code. You can use Shared Household after admin approval.")} action={<Button asChild className="rounded-xl"><a href="/setup">{pick("ফ্যামিলিতে যোগ দিন", "Family onboarding")}</a></Button>} /></main>;

  return <main className="mx-auto w-full max-w-[1550px] space-y-5 px-4 py-5 md:px-7 md:py-7">
    <section className="overflow-hidden rounded-3xl bg-[linear-gradient(125deg,#1e3a5f_0%,#0f766e_55%,#9a5b13_100%)] p-5 text-white shadow-xl md:p-7"><div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-center"><div className="max-w-2xl"><div className="flex items-center gap-2 text-sm text-cyan-100"><ShieldCheck className="size-4" /> {pick("পরিবারের দৈনন্দিন কার্যক্রম", "Everyday family operations")}</div><h1 className="mt-2 text-2xl font-bold tracking-tight md:text-4xl">{pick("শেয়ার্ড হাউসহোল্ড ম্যানেজমেন্ট", "Shared Household Management")}</h1><p className="mt-2 text-sm leading-6 text-white/75">{pick("বাজার, ইউটিলিটি বিল, দায়িত্ব, বিশ্বস্ত সেবা, মেরামত ও রসিদ—বাসার দৈনন্দিন সব কাজ এক জায়গায়।", "Manage shopping, utility bills, responsibilities, trusted services, maintenance and receipts in one place.")}</p></div><div className="flex flex-wrap gap-2"><Button variant="secondary" className="rounded-xl" onClick={() => void exportXlsx()} disabled={exporting}>{exporting ? <LoaderCircle className="size-4 animate-spin" /> : <Download className="size-4" />} {pick("সব XLSX", "Export all XLSX")}</Button><Button variant="secondary" className="rounded-xl" onClick={() => setUploadOpen(true)} disabled={!uploadTargets.length || migrationRequired}><Upload className="size-4" /> {pick("রসিদ", "Receipt")}</Button><Button className="rounded-xl bg-cyan-500 text-slate-950 hover:bg-cyan-400" onClick={() => openCreate("item")} disabled={!filteredLists.length || migrationRequired}><ShoppingBasket className="size-4" /> {pick("আইটেম যোগ করুন", "Add item")}</Button></div></div></section>
    {migrationRequired ? <div className="rounded-2xl border border-amber-300 bg-amber-50 p-4 text-sm text-amber-950 dark:border-amber-800 dark:bg-amber-950/35 dark:text-amber-100">{pick("শেয়ার্ড হাউসহোল্ড ডেটা সক্রিয় করতে Supabase SQL Editor-এ", "To activate Shared Household data, run")} <b>supabase/migrations/20260927_shared_household.sql</b> {pick("চালান।", "in the Supabase SQL Editor.")}</div> : null}
    {feedback ? <div className="flex items-start justify-between gap-3 rounded-2xl border bg-card px-4 py-3 text-sm"><span>{feedback}</span><Button size="icon-xs" variant="ghost" onClick={() => setFeedback(null)}><X /></Button></div> : null}
    <section className="flex flex-col justify-between gap-3 rounded-2xl border bg-card p-4 sm:flex-row sm:items-center"><div><p className="font-semibold">{pick("বাসা ফিল্টার", "Household filter")}</p><p className="text-xs text-muted-foreground">{pick("নির্দিষ্ট বাসা অথবা পুরো পরিবারের কার্যক্রম দেখুন", "View one household or the entire family's operations")}</p></div><div className="flex flex-wrap gap-2"><Native value={selectedHousehold} onChange={setSelectedHousehold} options={[["all", pick("সব বাসা", "All households")], ...visibleHouseholds.map((item) => [item.id, item.name])]} />{canManage && selectedHousehold !== "all" ? <Button variant="outline" className="rounded-xl" onClick={() => { const selected = households.find((item) => item.id === selectedHousehold); if (selected) openEdit("household", selected); }}><Pencil /> {pick("সম্পাদনা", "Edit")}</Button> : null}{canManage ? <Button className="rounded-xl" onClick={() => openCreate("household")} disabled={migrationRequired}><HousePlus /> {pick("বাসা", "Household")}</Button> : null}</div></section>
    <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric icon={<ShoppingBasket />} label={pick("বাজার বাকি", "Shopping needed")} value={String(openItems.length)} note={pick(`${filteredLists.filter((item) => item.status === "active").length}টি সক্রিয় তালিকা`, `${filteredLists.filter((item) => item.status === "active").length} active lists`)} tone="cyan" /><Metric icon={<Zap />} label={pick("ইউটিলিটি বকেয়া", "Utility due")} value={money.format(dueAmount)} note={pick(`${dueBills.length}টি বকেয়া বা মেয়াদোত্তীর্ণ`, `${dueBills.length} pending or overdue`)} tone="amber" /><Metric icon={<ClipboardCheck />} label={pick("খোলা কাজ", "Open tasks")} value={String(openTasks.length)} note={pick(`${openTasks.filter((item) => item.priority === "urgent").length}টি জরুরি`, `${openTasks.filter((item) => item.priority === "urgent").length} urgent`)} tone="blue" /><Metric icon={<Wrench />} label={pick("মেরামত", "Maintenance")} value={String(openMaintenance.length)} note={pick(`${openMaintenance.filter((item) => item.urgency === "critical").length}টি সংকটপূর্ণ`, `${openMaintenance.filter((item) => item.urgency === "critical").length} critical`)} tone="rose" /></section>

    <Tabs defaultValue="shopping" className="space-y-4"><TabsList className="h-auto w-full justify-start overflow-x-auto rounded-2xl bg-muted/70 p-1"><TabsTrigger value="shopping">{pick("বাজার", "Shopping")}</TabsTrigger><TabsTrigger value="bills">{pick("বিল", "Bills")}</TabsTrigger><TabsTrigger value="tasks">{pick("কাজ", "Tasks")}</TabsTrigger><TabsTrigger value="maintenance">{pick("মেরামত", "Maintenance")}</TabsTrigger><TabsTrigger value="services">{pick("সেবা", "Services")}</TabsTrigger><TabsTrigger value="documents">{pick("ডকুমেন্ট", "Documents")}</TabsTrigger></TabsList>
      <TabsContent value="shopping"><Section title="Shared shopping lists" description="Real-time প্রয়োজন, assignment, budget ও purchased cost" action={<div className="flex gap-2"><Button variant="outline" className="rounded-xl" onClick={() => openCreate("list")} disabled={!visibleHouseholds.length || migrationRequired}><Plus /> {pick("তালিকা", "List")}</Button><Button className="rounded-xl" onClick={() => openCreate("item")} disabled={!filteredLists.length || migrationRequired}><Plus /> {pick("আইটেম", "Item")}</Button></div>}><div className="grid gap-4 p-4 xl:grid-cols-2">{filteredLists.map((list) => <ShoppingListCard key={list.id} list={list} items={items.filter((item) => item.list_id === list.id)} household={householdName(list.household_id)} saving={saving} canManage={canManage} onAdd={() => openCreate("item", { listId: list.id })} onEditList={() => openEdit("list", list)} onDeleteList={() => void remove("list", list.id)} onEditItem={(item) => openEdit("item", item)} onDeleteItem={(item) => void remove("item", item.id)} onListStatus={(value) => void status("list", list.id, value)} onItemStatus={(item, value) => { if (value === "purchased") setStatusDraft({ kind: "item", item, actualCost: String(n(item.estimated_cost)) }); else void status("item", item.id, value); }} />)}{!filteredLists.length ? <div className="xl:col-span-2"><Empty icon={<ShoppingBasket />} title="Shopping list নেই" text="সাপ্তাহিক বাজার, medicine অথবা household supplies-এর list তৈরি করুন।" /></div> : null}</div></Section></TabsContent>
      <TabsContent value="bills"><Section title="Utility bills & reminders" description="Due date, recurrence, overdue alert ও payment history" action={canManage ? <Button className="rounded-xl" onClick={() => openCreate("bill")} disabled={!visibleHouseholds.length || migrationRequired}><Plus /> {pick("বিল", "Bill")}</Button> : undefined}><TableBox><Table><TableHeader><TableRow><TableHead>{pick("শেষ তারিখ", "Due")}</TableHead><TableHead>{pick("বিল", "Bill")}</TableHead><TableHead>{pick("বাসা", "Household")}</TableHead><TableHead>{pick("পরিমাণ", "Amount")}</TableHead><TableHead>{pick("পুনরাবৃত্তি", "Recurrence")}</TableHead><TableHead>{pick("স্ট্যাটাস", "Status")}</TableHead>{canManage ? <TableHead /> : null}</TableRow></TableHeader><TableBody>{filteredBills.map((bill) => <TableRow key={bill.id}><TableCell className={effectiveBillStatus(bill) === "overdue" ? "font-bold text-destructive" : ""}>{date.format(new Date(bill.due_date))}</TableCell><TableCell><p className="font-semibold">{bill.title}</p><p className="text-xs text-muted-foreground">{bill.provider || householdValueLabel(bill.category, locale)}{bill.account_number ? ` · ${bill.account_number}` : ""}</p></TableCell><TableCell>{householdName(bill.household_id)}</TableCell><TableCell className="font-bold">{money.format(n(bill.amount))}</TableCell><TableCell className="capitalize">{householdValueLabel(bill.recurrence, locale)}</TableCell><TableCell><Status value={effectiveBillStatus(bill)} /></TableCell>{canManage ? <TableCell><Menu disabled={saving} items={[...(bill.status === "paid" ? [] : [["Mark paid", () => setStatusDraft({ kind: "bill", bill, paymentMethod: bill.payment_method ?? "mobile", reference: bill.reference ?? "" })], ["Skip", () => void status("bill", bill.id, "skipped")]] as Array<[string, () => void]>), ["Edit details", () => openEdit("bill", bill)], ...(bill.status !== "paid" ? [["Delete permanently", () => void remove("bill", bill.id)]] as Array<[string, () => void]> : [])]} /></TableCell> : null}</TableRow>)}<EmptyRows show={!filteredBills.length} columns={canManage ? 7 : 6} /></TableBody></Table></TableBox></Section></TabsContent>
      <TabsContent value="tasks"><Section title="Shared task board" description="Assignment, deadline, recurrence এবং completion" action={<Button className="rounded-xl" onClick={() => openCreate("task")} disabled={!visibleHouseholds.length || migrationRequired}><Plus /> {pick("কাজ", "Task")}</Button>}><div className="grid gap-3 p-4 md:grid-cols-2 xl:grid-cols-3">{filteredTasks.map((task) => <TaskCard key={task.id} task={task} household={householdName(task.household_id)} saving={saving} canManage={canManage} onStatus={(value) => void status("task", task.id, value)} onEdit={() => openEdit("task", task)} onDelete={() => void remove("task", task.id)} />)}{!filteredTasks.length ? <div className="md:col-span-2 xl:col-span-3"><Empty icon={<ListChecks />} title="Shared task নেই" text="বাজার, cleaning, cooking, care বা bill payment দায়িত্ব দিন।" /></div> : null}</div></Section></TabsContent>
      <TabsContent value="maintenance"><Section title="Maintenance control" description="Issue report, approval, vendor, schedule এবং actual cost" action={<Button className="rounded-xl" onClick={() => openCreate("maintenance")} disabled={!visibleHouseholds.length || migrationRequired}><Plus /> {pick("সমস্যা জানান", "Report issue")}</Button>}><div className="grid gap-3 p-4 md:grid-cols-2 xl:grid-cols-3">{filteredMaintenance.map((request) => <MaintenanceCard key={request.id} request={request} household={householdName(request.household_id)} canManage={canManage} saving={saving} onStatus={(value) => setStatusDraft({ kind: "maintenance", request, nextStatus: value, actualCost: String(n(request.actual_cost) || n(request.estimated_cost)), vendor: request.assigned_vendor_name ?? "", scheduledAt: request.scheduled_at?.slice(0, 16) ?? "" })} onEdit={() => openEdit("maintenance", request)} onDelete={() => void remove("maintenance", request.id)} />)}{!filteredMaintenance.length ? <div className="md:col-span-2 xl:col-span-3"><Empty icon={<Wrench />} title="Maintenance issue নেই" text="Electrical, plumbing, appliance বা building সমস্যা report করুন।" /></div> : null}</div></Section></TabsContent>
      <TabsContent value="services"><Section title="Trusted service directory" description="Electrician, plumber, driver, cleaner ও caregiver contacts" action={canManage ? <Button className="rounded-xl" onClick={() => openCreate("contact")} disabled={migrationRequired}><Plus /> {pick("যোগাযোগ", "Contact")}</Button> : undefined}><div className="grid gap-3 p-4 md:grid-cols-2 xl:grid-cols-3">{contacts.filter((item) => selectedHousehold === "all" || !item.household_id || item.household_id === selectedHousehold).map((contact) => <article key={contact.id} className="rounded-2xl border p-4"><div className="flex items-start justify-between"><span className="grid size-10 place-items-center rounded-xl bg-primary/10 text-primary"><Settings2 className="size-5" /></span><div className="flex gap-2">{contact.is_trusted ? <Badge className="gap-1"><BadgeCheck className="size-3" /> {pick("বিশ্বস্ত", "Trusted")}</Badge> : null}<Status value={contact.status} />{canManage ? <Menu disabled={saving} items={[...(contact.status === "active" ? [["Deactivate", () => void status("contact", contact.id, "inactive")]] as Array<[string, () => void]> : [["Activate", () => void status("contact", contact.id, "active")]] as Array<[string, () => void]>), ["Edit details", () => openEdit("contact", contact)], ["Delete permanently", () => void remove("contact", contact.id)]]} /> : null}</div></div><h3 className="mt-3 font-bold">{contact.name}</h3><p className="text-sm capitalize text-muted-foreground">{householdValueLabel(contact.service_type, locale)}</p><a className="mt-3 flex items-center gap-2 text-sm font-semibold text-primary" href={`tel:${contact.phone}`}><Phone className="size-4" /> {contact.phone}</a><p className="mt-2 flex items-center gap-1 text-xs text-amber-600"><Star className="size-3 fill-current" /> {n(contact.rating).toFixed(1)} / 5</p></article>)}{!contacts.length ? <div className="md:col-span-2 xl:col-span-3"><Empty icon={<Phone />} title="Service contact নেই" text="বিশ্বস্ত service provider যোগ করুন।" /></div> : null}</div></Section></TabsContent>
      <TabsContent value="documents"><Section title="Household receipt vault" description="Shopping receipt, bill invoice, warranty ও maintenance quotation" action={<Button className="rounded-xl" onClick={() => setUploadOpen(true)} disabled={!uploadTargets.length || migrationRequired}><Upload /> {pick("আপলোড", "Upload")}</Button>}><div className="grid gap-3 p-4 md:grid-cols-2 xl:grid-cols-3">{documents.map((document) => <article key={document.id} className="rounded-2xl border p-4 transition hover:border-primary/40 hover:bg-muted/30"><div className="flex items-start justify-between"><a href={`/api/household-document/${document.id}`} target="_blank" rel="noreferrer" className="grid size-10 place-items-center rounded-xl bg-primary/10 text-primary"><FileText className="size-5" /></a>{canManage ? <Button size="icon-sm" variant="ghost" className="text-destructive" disabled={saving} onClick={() => void deleteDocument(document.id)}><Trash2 /><span className="sr-only">{pick("নথি মুছুন", "Delete document")}</span></Button> : null}</div><a href={`/api/household-document/${document.id}`} target="_blank" rel="noreferrer"><p className="mt-3 font-semibold">{document.title}</p><p className="mt-1 truncate text-xs text-muted-foreground">{document.file_name}</p><p className="mt-3 text-xs text-muted-foreground">{householdValueLabel(document.document_type, locale)} · {document.uploaded_by_name} · {date.format(new Date(document.created_at))}</p></a></article>)}{!documents.length ? <div className="md:col-span-2 xl:col-span-3"><Empty icon={<ReceiptText />} title="Document নেই" text="Receipt, invoice, warranty বা quotation upload করুন।" /></div> : null}</div></Section></TabsContent>
    </Tabs>

    <Dialog open={Boolean(statusDraft)} onOpenChange={(open) => { if (!open && !saving) setStatusDraft(null); }}>
      <DialogContent className="rounded-3xl sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{statusDraft?.kind === "item" ? pick("কেনাকাটার খরচ", "Shopping purchase") : statusDraft?.kind === "bill" ? pick("বিল পরিশোধ", "Pay utility bill") : pick("মেরামতের অবস্থা", "Maintenance status")}</DialogTitle>
          <DialogDescription>{statusDraft?.kind === "item" ? statusDraft.item.item_name : statusDraft?.kind === "bill" ? statusDraft.bill.title : statusDraft?.request.title}</DialogDescription>
        </DialogHeader>
        {statusDraft?.kind === "item" ? <Field label={pick("প্রকৃত খরচ", "Actual cost")}><Input type="number" min="0" step="0.01" value={statusDraft.actualCost} onChange={(event) => setStatusDraft({ ...statusDraft, actualCost: event.target.value })} /></Field> : null}
        {statusDraft?.kind === "bill" ? <div className="grid gap-4"><Field label={pick("পেমেন্ট পদ্ধতি", "Payment method")}><Native value={statusDraft.paymentMethod} onChange={(value) => setStatusDraft({ ...statusDraft, paymentMethod: value })} options={[["cash", pick("নগদ", "Cash")], ["bank", pick("ব্যাংক", "Bank")], ["mobile", pick("মোবাইল ব্যাংকিং", "Mobile banking")], ["card", pick("কার্ড", "Card")], ["other", pick("অন্যান্য", "Other")]]} /></Field><Field label={pick("পেমেন্ট রেফারেন্স", "Payment reference")}><Input maxLength={180} value={statusDraft.reference} onChange={(event) => setStatusDraft({ ...statusDraft, reference: event.target.value })} /></Field></div> : null}
        {statusDraft?.kind === "maintenance" ? <div className="grid gap-4"><p className="text-sm text-muted-foreground">{pick("নতুন অবস্থা", "New status")}: {householdValueLabel(statusDraft.nextStatus, locale)}</p>{["approved", "scheduled", "in_progress"].includes(statusDraft.nextStatus) ? <Field label={pick("সেবাদাতা / সেবাকর্মী", "Vendor / service person")}><Input maxLength={180} value={statusDraft.vendor} onChange={(event) => setStatusDraft({ ...statusDraft, vendor: event.target.value })} /></Field> : null}{statusDraft.nextStatus === "scheduled" ? <Field label={pick("সময়সূচি", "Schedule")}><Input type="datetime-local" value={statusDraft.scheduledAt} onChange={(event) => setStatusDraft({ ...statusDraft, scheduledAt: event.target.value })} /></Field> : null}{statusDraft.nextStatus === "completed" ? <Field label={pick("প্রকৃত খরচ", "Actual cost")}><Input type="number" min="0" step="0.01" value={statusDraft.actualCost} onChange={(event) => setStatusDraft({ ...statusDraft, actualCost: event.target.value })} /></Field> : null}</div> : null}
        <DialogFooter><Button variant="outline" className="rounded-xl" disabled={saving} onClick={() => setStatusDraft(null)}>{pick("বাতিল", "Cancel")}</Button><Button className="rounded-xl" disabled={saving} onClick={() => void submitStatusDraft()}>{saving ? <LoaderCircle className="size-4 animate-spin" /> : <CheckCircle2 className="size-4" />} {pick("চালিয়ে যান", "Continue")}</Button></DialogFooter>
      </DialogContent>
    </Dialog>
    <Dialog open={Boolean(kind)} onOpenChange={(open) => { if (!open) { setKind(null); setEditingRecord(null); } }}><DialogContent className="max-h-[90vh] overflow-y-auto rounded-3xl sm:max-w-2xl"><DialogHeader><DialogTitle>{kind ? (locale === "bn" ? titlesBn[kind] : titlesEn[kind]) : pick("নতুন রেকর্ড", "New record")} {editingRecord ? pick("সম্পাদনা", "edit") : ""}</DialogTitle><DialogDescription>{pick(`হাউসহোল্ড কার্যক্রমের প্রয়োজনীয় তথ্য ${editingRecord ? "হালনাগাদ করুন" : "দিন"}।`, `${editingRecord ? "Update" : "Enter"} the required household operation details.`)}</DialogDescription></DialogHeader>{kind ? <CreateForm kind={kind} form={form} setForm={setForm} households={visibleHouseholds} lists={lists.filter((item) => item.status === "active")} contacts={contacts.filter((item) => item.status === "active")} canManage={canManage} /> : null}<DialogFooter><Button variant="outline" className="rounded-xl" onClick={() => { setKind(null); setEditingRecord(null); }}>{pick("বাতিল", "Cancel")}</Button><Button className="rounded-xl" onClick={() => void create()} disabled={saving}>{saving ? <LoaderCircle className="size-4 animate-spin" /> : editingRecord ? <Pencil className="size-4" /> : <CheckCircle2 className="size-4" />} {editingRecord ? pick("আপডেট", "Update") : pick("সেভ", "Save")}</Button></DialogFooter></DialogContent></Dialog>
    <Dialog open={uploadOpen} onOpenChange={setUploadOpen}><DialogContent className="rounded-3xl sm:max-w-xl"><DialogHeader><DialogTitle>{pick("হাউসহোল্ড ডকুমেন্ট আপলোড", "Household document upload")}</DialogTitle><DialogDescription>{pick("JPG, PNG, WebP, PDF বা Word; সর্বোচ্চ ১২ MB।", "JPG, PNG, WebP, PDF or Word; maximum 12 MB.")}</DialogDescription></DialogHeader><div className="grid gap-4"><Field label={pick("সংযুক্ত রেকর্ড", "Linked record")}><Native value={uploadForm.target ?? ""} onChange={(value) => setUploadForm((old) => ({ ...old, target: value }))} options={uploadTargets.map((item) => [item.value, item.label])} placeholder={pick("রেকর্ড নির্বাচন করুন", "Select a record")} /></Field><Field label={pick("ধরন", "Type")}><Native value={uploadForm.documentType} onChange={(value) => setUploadForm((old) => ({ ...old, documentType: value }))} options={[["receipt", pick("রসিদ", "Receipt")], ["invoice", pick("ইনভয়েস", "Invoice")], ["warranty", pick("ওয়ারেন্টি", "Warranty")], ["quotation", pick("কোটেশন", "Quotation")], ["other", pick("অন্যান্য", "Other")]]} /></Field><Field label={pick("শিরোনাম", "Title")}><Input value={uploadForm.title ?? ""} onChange={(event) => setUploadForm((old) => ({ ...old, title: event.target.value }))} /></Field><Field label={pick("ফাইল", "File")}><Input type="file" accept="image/jpeg,image/png,image/webp,application/pdf,.doc,.docx" onChange={(event) => setUploadFile(event.target.files?.[0] ?? null)} /></Field></div><DialogFooter><Button variant="outline" className="rounded-xl" onClick={() => setUploadOpen(false)}>{pick("বাতিল", "Cancel")}</Button><Button className="rounded-xl" onClick={() => void upload()} disabled={saving || !uploadFile}><Upload /> {pick("আপলোড", "Upload")}</Button></DialogFooter></DialogContent></Dialog>
  </main>;
}

function CreateForm({ kind, form, setForm, households, lists, contacts, canManage }: { kind: Kind; form: Form; setForm: (form: Form) => void; households: Household[]; lists: ShoppingList[]; contacts: ServiceContact[]; canManage: boolean }) {
  const { locale } = useLocale();
  const labelsBn: Record<string, string> = { Household: "বাসা", "Household name": "বাসার নাম", City: "শহর", Address: "ঠিকানা", Notes: "নোট", "List title": "তালিকার শিরোনাম", Budget: "বাজেট", "Needed by": "প্রয়োজনের তারিখ", Description: "বিবরণ", "Shopping list": "বাজারের তালিকা", "Item name": "আইটেমের নাম", Category: "শ্রেণি", Quantity: "পরিমাণ", Unit: "একক", "Estimated cost": "আনুমানিক খরচ", Priority: "অগ্রাধিকার", "Assigned to": "দায়িত্বপ্রাপ্ত", "Bill title": "বিলের শিরোনাম", Provider: "সেবাদাতা", "Account / meter number": "অ্যাকাউন্ট / মিটার নম্বর", "Billing month": "বিলের মাস", Amount: "পরিমাণ", "Due date": "শেষ তারিখ", Recurrence: "পুনরাবৃত্তি", "Task title": "কাজের শিরোনাম", "Due time": "শেষ সময়", "Service person / company": "সেবাদাতা ব্যক্তি / প্রতিষ্ঠান", Service: "সেবা", Phone: "ফোন", "Alternate phone": "বিকল্প ফোন", "Rating 0-5": "রেটিং ০–৫", "Trust status": "বিশ্বস্ততার অবস্থা", "Issue title": "সমস্যার শিরোনাম", Urgency: "জরুরিতা", "Service contact": "সেবা যোগাযোগ", "Vendor name": "সেবাদাতার নাম", Schedule: "সময়সূচি", "সমস্যার বিস্তারিত": "সমস্যার বিস্তারিত" };
  const optionsBn: Record<string, string> = { Grocery: "মুদিপণ্য", Medicine: "ওষুধ", Household: "গৃহস্থালি", Baby: "শিশু", Personal: "ব্যক্তিগত", Other: "অন্যান্য", Low: "কম", Normal: "সাধারণ", High: "উচ্চ", Urgent: "জরুরি", Electricity: "বিদ্যুৎ", Gas: "গ্যাস", Water: "পানি", Internet: "ইন্টারনেট", Phone: "ফোন", Rent: "ভাড়া", Maintenance: "মেরামত", None: "কোনোটি নয়", Monthly: "মাসিক", Quarterly: "ত্রৈমাসিক", Yearly: "বার্ষিক", Cleaning: "পরিচ্ছন্নতা", Cooking: "রান্না", Shopping: "বাজার", Care: "যত্ন", Repair: "মেরামত", Bill: "বিল", Daily: "দৈনিক", Weekly: "সাপ্তাহিক", Electrician: "ইলেকট্রিশিয়ান", Plumber: "প্লাম্বার", Cleaner: "পরিচ্ছন্নতাকর্মী", Driver: "ড্রাইভার", Technician: "টেকনিশিয়ান", Caregiver: "কেয়ারগিভার", Security: "নিরাপত্তা", "Normal contact": "সাধারণ যোগাযোগ", "Trusted / verified": "বিশ্বস্ত / যাচাইকৃত", Electrical: "বিদ্যুৎ", Plumbing: "প্লাম্বিং", Appliance: "যন্ত্রপাতি", Building: "ভবন", Critical: "সংকটপূর্ণ" };
  const placeholdersBn: Record<string, string> = { "Household নির্বাচন করুন": "বাসা নির্বাচন করুন", "List নির্বাচন করুন": "তালিকা নির্বাচন করুন", Optional: "ঐচ্ছিক" };
  const labelFor = (value: string) => locale === "bn" ? labelsBn[value] ?? value : value;
  const placeholderFor = (value?: string) => value && locale === "bn" ? placeholdersBn[value] ?? value : value;
  const set = (key: string, value: string) => setForm({ ...form, [key]: value });
  const input = (key: string, label: string, type = "text", props: Record<string, string> = {}) => <Field label={labelFor(label)}><Input type={type} value={form[key] ?? ""} onChange={(event) => set(key, event.target.value)} {...props} /></Field>;
  const select = (key: string, label: string, options: string[][], placeholder?: string) => <Field label={labelFor(label)}><Native value={form[key]} onChange={(value) => set(key, value)} options={options.map(([value, text]) => [value, locale === "bn" ? optionsBn[text] ?? text : text])} placeholder={placeholderFor(placeholder)} /></Field>;
  const household = select("householdId", "Household", households.map((item) => [item.id, item.name]), "Household নির্বাচন করুন");
  const notes = <Field label={labelFor(kind === "maintenance" ? "সমস্যার বিস্তারিত" : "Notes")}><Textarea rows={4} value={form[kind === "maintenance" ? "description" : "notes"] ?? ""} onChange={(event) => set(kind === "maintenance" ? "description" : "notes", event.target.value)} /></Field>;
  if (kind === "household") return <div className="grid gap-4 py-2 sm:grid-cols-2">{input("name", "Household name")}{input("city", "City")}{input("address", "Address")}<div className="sm:col-span-2">{notes}</div></div>;
  if (kind === "list") return <div className="grid gap-4 py-2 sm:grid-cols-2">{household}{input("title", "List title")}{input("budgetAmount", "Budget", "number", { min: "0" })}{input("neededBy", "Needed by", "date")}<div className="sm:col-span-2">{input("description", "Description")}</div></div>;
  if (kind === "item") return <div className="grid gap-4 py-2 sm:grid-cols-2">{select("listId", "Shopping list", lists.map((item) => [item.id, item.title]), "List নির্বাচন করুন")}{input("itemName", "Item name")}{select("category", "Category", [["grocery", "Grocery"], ["medicine", "Medicine"], ["household", "Household"], ["baby", "Baby"], ["personal", "Personal"], ["other", "Other"]])}{input("quantity", "Quantity", "number", { min: "0.01" })}{input("unit", "Unit")}{input("estimatedCost", "Estimated cost", "number", { min: "0" })}{select("priority", "Priority", priorityOptions)}{input("assignedToName", "Assigned to")}<div className="sm:col-span-2">{notes}</div></div>;
  if (kind === "bill") return <div className="grid gap-4 py-2 sm:grid-cols-2">{household}{input("title", "Bill title")}{select("category", "Category", [["electricity", "Electricity"], ["gas", "Gas"], ["water", "Water"], ["internet", "Internet"], ["phone", "Phone"], ["rent", "Rent"], ["maintenance", "Maintenance"], ["other", "Other"]])}{input("provider", "Provider")}{input("accountNumber", "Account / meter number")}{input("billingMonth", "Billing month", "date")}{input("amount", "Amount", "number", { min: "1" })}{input("dueDate", "Due date", "date")}{select("recurrence", "Recurrence", [["none", "None"], ["monthly", "Monthly"], ["quarterly", "Quarterly"], ["yearly", "Yearly"]])}<div className="sm:col-span-2">{notes}</div></div>;
  if (kind === "task") return <div className="grid gap-4 py-2 sm:grid-cols-2">{household}{input("title", "Task title")}{select("category", "Category", [["cleaning", "Cleaning"], ["cooking", "Cooking"], ["shopping", "Shopping"], ["care", "Care"], ["repair", "Repair"], ["bill", "Bill"], ["other", "Other"]])}{input("assignedToName", "Assigned to")}{input("dueAt", "Due time", "datetime-local")}{select("recurrence", "Recurrence", [["none", "None"], ["daily", "Daily"], ["weekly", "Weekly"], ["monthly", "Monthly"]])}{select("priority", "Priority", priorityOptions)}<div className="sm:col-span-2">{notes}</div></div>;
  if (kind === "contact") return <div className="grid gap-4 py-2 sm:grid-cols-2">{household}{input("name", "Service person / company")}{select("serviceType", "Service", [["electrician", "Electrician"], ["plumber", "Plumber"], ["cleaner", "Cleaner"], ["driver", "Driver"], ["technician", "Technician"], ["caregiver", "Caregiver"], ["security", "Security"], ["other", "Other"]])}{input("phone", "Phone", "tel")}{input("alternatePhone", "Alternate phone", "tel")}{input("rating", "Rating 0-5", "number", { min: "0", max: "5", step: "0.5" })}{canManage ? select("isTrusted", "Trust status", [["false", "Normal contact"], ["true", "Trusted / verified"]]) : null}{input("address", "Address")}<div className="sm:col-span-2">{notes}</div></div>;
  return <div className="grid gap-4 py-2 sm:grid-cols-2">{household}{input("title", "Issue title")}{select("category", "Category", [["electrical", "Electrical"], ["plumbing", "Plumbing"], ["appliance", "Appliance"], ["building", "Building"], ["cleaning", "Cleaning"], ["security", "Security"], ["other", "Other"]])}{select("urgency", "Urgency", [["normal", "Normal"], ["high", "High"], ["critical", "Critical"]])}{input("estimatedCost", "Estimated cost", "number", { min: "0" })}{select("serviceContactId", "Service contact", contacts.map((item) => [item.id, `${item.name} · ${householdValueLabel(item.service_type, locale)}`]), "Optional")}{input("assignedVendorName", "Vendor name")}{input("scheduledAt", "Schedule", "datetime-local")}<div className="sm:col-span-2">{notes}</div></div>;
}

const priorityOptions = [["low", "Low"], ["normal", "Normal"], ["high", "High"], ["urgent", "Urgent"]];
function Field({ label, children }: { label: string; children: ReactNode }) { return <div className="grid gap-2"><Label>{label}</Label>{children}</div>; }
function Native({ value, onChange, options, placeholder }: { value?: string; onChange: (value: string) => void; options: string[][]; placeholder?: string }) { return <select value={value ?? ""} onChange={(event) => onChange(event.target.value)} className="h-10 min-w-48 rounded-md border border-input bg-background px-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/15">{placeholder ? <option value="">{placeholder}</option> : null}{options.map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select>; }
function effectiveBillStatus(bill: UtilityBill) { return bill.status === "pending" && new Date(`${bill.due_date}T23:59:59`).getTime() < Date.now() ? "overdue" : bill.status; }
function Metric({ icon, label, value, note, tone }: { icon: ReactNode; label: string; value: string; note: string; tone: "cyan" | "amber" | "blue" | "rose" }) { const colors = { cyan: "bg-cyan-500/10 text-cyan-700 dark:text-cyan-300", amber: "bg-amber-500/10 text-amber-700 dark:text-amber-300", blue: "bg-blue-500/10 text-blue-700 dark:text-blue-300", rose: "bg-rose-500/10 text-rose-700 dark:text-rose-300" }; return <Card className="rounded-2xl shadow-none"><CardContent className="flex items-start gap-4 p-5"><span className={`grid size-11 shrink-0 place-items-center rounded-2xl ${colors[tone]}`}>{icon}</span><div className="min-w-0"><p className="text-sm text-muted-foreground">{label}</p><p className="mt-1 truncate text-2xl font-black">{value}</p><p className="mt-1 text-xs text-muted-foreground">{note}</p></div></CardContent></Card>; }
function Section({ title, description, action, children }: { title: string; description: string; action?: ReactNode; children: ReactNode }) { const { locale } = useLocale(); const titlesBn: Record<string, string> = { "Shared shopping lists": "শেয়ার্ড বাজারের তালিকা", "Utility bills & reminders": "ইউটিলিটি বিল ও রিমাইন্ডার", "Shared task board": "শেয়ার্ড কাজের বোর্ড", "Maintenance control": "মেরামত নিয়ন্ত্রণ", "Trusted service directory": "বিশ্বস্ত সেবা ডিরেক্টরি", "Household receipt vault": "হাউসহোল্ড রসিদ ভল্ট" }; const descriptionsBn: Record<string, string> = { "Real-time প্রয়োজন, assignment, budget ও purchased cost": "রিয়েল-টাইম প্রয়োজন, দায়িত্ব, বাজেট ও ক্রয়মূল্য", "Due date, recurrence, overdue alert ও payment history": "শেষ তারিখ, পুনরাবৃত্তি, বকেয়া সতর্কতা ও পেমেন্ট ইতিহাস", "Assignment, deadline, recurrence এবং completion": "দায়িত্ব, সময়সীমা, পুনরাবৃত্তি ও সমাপ্তি", "Issue report, approval, vendor, schedule এবং actual cost": "সমস্যা রিপোর্ট, অনুমোদন, সেবাদাতা, সময়সূচি ও প্রকৃত খরচ", "Electrician, plumber, driver, cleaner ও caregiver contacts": "ইলেকট্রিশিয়ান, প্লাম্বার, ড্রাইভার, পরিচ্ছন্নতাকর্মী ও কেয়ারগিভার", "Shopping receipt, bill invoice, warranty ও maintenance quotation": "বাজারের রসিদ, বিল ইনভয়েস, ওয়ারেন্টি ও মেরামতের কোটেশন" }; return <Card className="overflow-hidden rounded-3xl py-0 shadow-none"><CardHeader className="flex-row items-start justify-between gap-4 border-b p-5 md:p-6"><div><CardTitle>{locale === "bn" ? titlesBn[title] ?? title : title}</CardTitle><p className="mt-1 text-sm text-muted-foreground">{locale === "bn" ? descriptionsBn[description] ?? description : description}</p></div>{action}</CardHeader><CardContent className="p-0">{children}</CardContent></Card>; }
function TableBox({ children }: { children: ReactNode }) { return <div className="overflow-x-auto">{children}</div>; }
function Status({ value }: { value: string }) { const { locale } = useLocale(); const good = ["active", "paid", "completed", "purchased"]; const bad = ["overdue", "cancelled", "unavailable", "inactive", "archived"]; const bn: Record<string, string> = { active: "সক্রিয়", paid: "পরিশোধিত", completed: "সম্পন্ন", purchased: "কেনা হয়েছে", overdue: "মেয়াদোত্তীর্ণ", cancelled: "বাতিল", unavailable: "অনুপলব্ধ", inactive: "নিষ্ক্রিয়", archived: "আর্কাইভ", pending: "অপেক্ষমাণ", todo: "করণীয়", in_progress: "চলমান", needed: "প্রয়োজন", reported: "রিপোর্ট করা", approved: "অনুমোদিত", scheduled: "নির্ধারিত", skipped: "এড়িয়ে যাওয়া" }; return <Badge variant={bad.includes(value) ? "destructive" : good.includes(value) ? "secondary" : "outline"} className="capitalize">{locale === "bn" ? bn[value] ?? value : value.replaceAll("_", " ")}</Badge>; }
function Menu({ items, disabled }: { items: Array<[string, () => void]>; disabled: boolean }) { const { locale } = useLocale(); const bn: Record<string, string> = { "Complete list": "তালিকা সম্পন্ন", Archive: "আর্কাইভ", Reopen: "পুনরায় চালু", "Edit details": "বিস্তারিত সম্পাদনা", "Delete permanently": "স্থায়ীভাবে মুছুন", Unavailable: "অনুপলব্ধ", Cancel: "বাতিল", "Needed again": "আবার প্রয়োজন", Start: "শুরু", Complete: "সম্পন্ন", "Back to todo": "করণীয়তে ফেরত", Approve: "অনুমোদন", Schedule: "সময়সূচি", Deactivate: "নিষ্ক্রিয়", Activate: "সক্রিয়", "Mark paid": "পরিশোধিত করুন", Skip: "এড়িয়ে যান" }; if (!items.length) return null; return <DropdownMenu><DropdownMenuTrigger asChild><Button size="icon-sm" variant="ghost" disabled={disabled}><MoreHorizontal /></Button></DropdownMenuTrigger><DropdownMenuContent align="end">{items.map(([label, run]) => <DropdownMenuItem key={label} onClick={run}>{locale === "bn" ? bn[label] ?? label : label}</DropdownMenuItem>)}</DropdownMenuContent></DropdownMenu>; }
function EmptyRows({ show, columns }: { show: boolean; columns: number }) { const { pick } = useLocale(); return show ? <TableRow><TableCell colSpan={columns} className="h-32 text-center text-muted-foreground">{pick("এখনও কোনো রেকর্ড নেই।", "No records yet.")}</TableCell></TableRow> : null; }
function Empty({ icon, title, text, action }: { icon: ReactNode; title: string; text: string; action?: ReactNode }) { const { locale } = useLocale(); const titlesBn: Record<string, string> = { "Shopping list নেই": "বাজারের তালিকা নেই", "Shared task নেই": "শেয়ার্ড কাজ নেই", "Maintenance issue নেই": "মেরামতের সমস্যা নেই", "Service contact নেই": "সেবা যোগাযোগ নেই", "Document নেই": "ডকুমেন্ট নেই", "Family access সক্রিয় নয়": "পারিবারিক অ্যাক্সেস সক্রিয় নয়" }; const textBn: Record<string, string> = { "সাপ্তাহিক বাজার, medicine অথবা household supplies-এর list তৈরি করুন।": "সাপ্তাহিক বাজার, ওষুধ অথবা গৃহস্থালি সামগ্রীর তালিকা তৈরি করুন।", "বাজার, cleaning, cooking, care বা bill payment দায়িত্ব দিন।": "বাজার, পরিচ্ছন্নতা, রান্না, যত্ন বা বিল পরিশোধের দায়িত্ব দিন।", "Electrical, plumbing, appliance বা building সমস্যা report করুন।": "বিদ্যুৎ, প্লাম্বিং, যন্ত্রপাতি বা ভবনের সমস্যা রিপোর্ট করুন।", "বিশ্বস্ত service provider যোগ করুন।": "বিশ্বস্ত সেবাদাতা যোগ করুন।", "Receipt, invoice, warranty বা quotation upload করুন।": "রসিদ, ইনভয়েস, ওয়ারেন্টি বা কোটেশন আপলোড করুন।" }; return <div className="flex min-h-52 flex-col items-center justify-center p-6 text-center"><span className="text-muted-foreground/50">{icon}</span><h3 className="mt-3 font-bold">{locale === "bn" ? titlesBn[title] ?? title : title}</h3><p className="mt-1 max-w-md text-sm text-muted-foreground">{locale === "bn" ? textBn[text] ?? text : text}</p>{action ? <div className="mt-4">{action}</div> : null}</div>; }
function ShoppingListCard({ list, items, household, saving, canManage, onAdd, onListStatus, onItemStatus, onEditList, onDeleteList, onEditItem, onDeleteItem }: { list: ShoppingList; items: ShoppingItem[]; household: string; saving: boolean; canManage: boolean; onAdd: () => void; onListStatus: (value: string) => void; onItemStatus: (item: ShoppingItem, value: string) => void; onEditList: () => void; onDeleteList: () => void; onEditItem: (item: ShoppingItem) => void; onDeleteItem: (item: ShoppingItem) => void }) { const { locale, pick } = useLocale(); const formatter = new Intl.NumberFormat(locale === "bn" ? "bn-BD" : "en-BD", { style: "currency", currency: "BDT", minimumFractionDigits: 0, maximumFractionDigits: 2 }); const purchased = items.filter((item) => item.status === "purchased"); const spent = purchased.reduce((sum, item) => sum + n(item.actual_cost), 0); const estimate = items.reduce((sum, item) => sum + n(item.estimated_cost), 0); const progress = items.length ? purchased.length / items.length * 100 : 0; const listActions: Array<[string, () => void]> = list.status === "active" ? [["Complete list", () => onListStatus("completed")], ["Archive", () => onListStatus("archived")]] : [["Reopen", () => onListStatus("active")]]; if (canManage) listActions.push(["Edit details", onEditList], ["Delete permanently", onDeleteList]); return <article className="overflow-hidden rounded-2xl border"><div className="border-b bg-muted/20 p-4"><div className="flex items-start justify-between gap-3"><div><div className="flex flex-wrap gap-2"><Status value={list.status} /><Badge variant="outline">{household}</Badge></div><h3 className="mt-2 text-lg font-bold">{list.title}</h3></div><div className="flex"><Button size="sm" variant="outline" className="rounded-xl" onClick={onAdd}><Plus /> {pick("আইটেম", "Item")}</Button><Menu disabled={saving} items={listActions} /></div></div><Progress value={progress} className="mt-4" /><div className="mt-2 flex flex-wrap justify-between gap-2 text-xs text-muted-foreground"><span>{purchased.length}/{items.length} {pick("কেনা হয়েছে", "purchased")}</span><span>{formatter.format(spent)} {pick("প্রকৃত", "actual")} · {formatter.format(estimate)} {pick("আনুমানিক", "estimated")} · {formatter.format(n(list.budget_amount))} {pick("বাজেট", "budget")}</span></div></div><div className="divide-y">{items.map((item) => <div key={item.id} className="flex items-center gap-3 p-3"><button type="button" onClick={() => onItemStatus(item, item.status === "purchased" ? "needed" : "purchased")} className={`grid size-8 shrink-0 place-items-center rounded-full border ${item.status === "purchased" ? "border-emerald-500 bg-emerald-500 text-white" : "border-border"}`}><CheckCircle2 className="size-4" /></button><div className="min-w-0 flex-1"><p className={`font-semibold ${item.status === "purchased" ? "text-muted-foreground line-through" : ""}`}>{item.item_name}</p><p className="text-xs text-muted-foreground">{n(item.quantity)} {householdValueLabel(item.unit, locale)} · {item.assigned_to_name || pick("দায়িত্ব দেওয়া হয়নি", "Unassigned")}</p></div><div className="text-right"><p className="text-sm font-semibold">{formatter.format(item.status === "purchased" ? n(item.actual_cost) : n(item.estimated_cost))}</p><Badge variant={item.priority === "urgent" ? "destructive" : "outline"}>{householdValueLabel(item.priority, locale)}</Badge></div><Menu disabled={saving} items={[...(item.status === "needed" ? [["Unavailable", () => onItemStatus(item, "unavailable")], ["Cancel", () => onItemStatus(item, "cancelled")]] as Array<[string, () => void]> : [["Needed again", () => onItemStatus(item, "needed")]] as Array<[string, () => void]>), ...(canManage ? [["Edit details", () => onEditItem(item)], ["Delete permanently", () => onDeleteItem(item)]] as Array<[string, () => void]> : [])]} /></div>)}{!items.length ? <p className="p-6 text-center text-sm text-muted-foreground">{pick("আইটেম যোগ করলে তালিকা এখানে দেখা যাবে।", "Added items will appear here.")}</p> : null}</div></article>; }
function TaskCard({ task, household, saving, canManage, onStatus, onEdit, onDelete }: { task: HouseholdTask; household: string; saving: boolean; canManage: boolean; onStatus: (value: string) => void; onEdit: () => void; onDelete: () => void }) { const { locale, pick } = useLocale(); const dateTime = new Intl.DateTimeFormat(locale === "bn" ? "bn-BD" : "en-BD", { dateStyle: "medium", timeStyle: "short" }); const workflow: Array<[string, () => void]> = task.status === "todo" ? [["Start", () => onStatus("in_progress")], ["Complete", () => onStatus("completed")], ["Cancel", () => onStatus("cancelled")]] : task.status === "in_progress" ? [["Complete", () => onStatus("completed")], ["Back to todo", () => onStatus("todo")]] : [["Reopen", () => onStatus("todo")]]; if (canManage) workflow.push(["Edit details", onEdit], ["Delete permanently", onDelete]); return <article className="rounded-2xl border p-4"><div className="flex items-start justify-between gap-3"><div className="flex flex-wrap gap-2"><Status value={task.status} /><Badge variant={task.priority === "urgent" ? "destructive" : "outline"}>{locale === "bn" ? householdValueBn[task.priority] ?? task.priority : task.priority}</Badge></div><Menu disabled={saving} items={workflow} /></div><h3 className="mt-3 font-bold">{task.title}</h3><p className="mt-1 text-sm text-muted-foreground">{household} · {locale === "bn" ? householdValueBn[task.category] ?? task.category : task.category}</p><div className="mt-3 rounded-xl bg-muted/45 p-3 text-sm"><p><b>{pick("দায়িত্বপ্রাপ্ত:", "Assigned:")}</b> {task.assigned_to_name || pick("যে কেউ", "Anyone")}</p><p className="mt-1"><b>{pick("শেষ সময়:", "Due:")}</b> {task.due_at ? dateTime.format(new Date(task.due_at)) : pick("সময়সীমা নেই", "No deadline")}</p><p className="mt-1"><b>{pick("পুনরাবৃত্তি:", "Repeats:")}</b> {locale === "bn" ? householdValueBn[task.recurrence] ?? task.recurrence : task.recurrence}</p></div></article>; }
function MaintenanceCard({ request, household, canManage, saving, onStatus, onEdit, onDelete }: { request: MaintenanceRequest; household: string; canManage: boolean; saving: boolean; onStatus: (value: string) => void; onEdit: () => void; onDelete: () => void }) {
  const { locale, pick } = useLocale();
  const formatter = new Intl.NumberFormat(locale === "bn" ? "bn-BD" : "en-BD", { style: "currency", currency: "BDT", minimumFractionDigits: 0, maximumFractionDigits: 2 });
  const items: Array<[string, () => void]> = canManage ? request.status === "reported" ? [["Approve", () => onStatus("approved")], ["Cancel", () => onStatus("cancelled")]] : request.status === "approved" ? [["Schedule", () => onStatus("scheduled")], ["Start", () => onStatus("in_progress")]] : ["scheduled", "in_progress"].includes(request.status) ? [["Complete", () => onStatus("completed")]] : [] : request.status === "reported" ? [["Cancel", () => onStatus("cancelled")]] : [];
  if (canManage) items.push(["Edit details", onEdit]);
  if (canManage && request.status !== "completed") items.push(["Delete permanently", onDelete]);
  return <article className="rounded-2xl border p-4"><div className="flex items-start justify-between gap-3"><div className="flex flex-wrap gap-2"><Badge variant={request.urgency === "critical" ? "destructive" : "secondary"}>{locale === "bn" ? householdValueBn[request.urgency] ?? request.urgency : request.urgency}</Badge><Status value={request.status} /></div><Menu disabled={saving} items={items} /></div><h3 className="mt-3 font-bold">{request.title}</h3><p className="mt-1 text-xs text-muted-foreground">{household} · {locale === "bn" ? householdValueBn[request.category] ?? request.category : request.category} · {pick("রিপোর্ট করেছেন", "by")} {request.reported_by_name}</p><p className="mt-3 line-clamp-3 text-sm text-muted-foreground">{request.description}</p><div className="mt-3 grid grid-cols-2 gap-2"><div className="rounded-xl bg-muted/45 p-3"><p className="text-xs text-muted-foreground">{pick("আনুমানিক", "Estimated")}</p><p className="font-bold">{formatter.format(n(request.estimated_cost))}</p></div><div className="rounded-xl bg-muted/45 p-3"><p className="text-xs text-muted-foreground">{pick("প্রকৃত", "Actual")}</p><p className="font-bold">{formatter.format(n(request.actual_cost))}</p></div></div>{request.assigned_vendor_name ? <p className="mt-3 text-xs text-muted-foreground">{pick("সেবাদাতা:", "Vendor:")} {request.assigned_vendor_name}</p> : null}</article>;
}
